import requests

BASE_URL = "https://api.socbench.example"
session = requests.Session()

# Retrieve the top-rated sustainable products across categories.
top_response = session.get(f"{BASE_URL}/products/top-rated")
top_response.raise_for_status()
top_data = top_response.json()

# Extract product IDs from the response, accommodating common response shapes.
if isinstance(top_data, list):
    products = top_data
elif isinstance(top_data, dict):
    products = top_data.get("products", [])
else:
    products = []

product_ids = []
for product in products:
    if isinstance(product, dict):
        product_id = product.get("productId") or product.get("product_id") or product.get("id")
        if product_id is not None and str(product_id) not in product_ids:
            product_ids.append(str(product_id))

# Fetch detailed product information and pricing for each top-rated product.
details = {}
prices = {}
for product_id in product_ids:
    detail_response = session.get(f"{BASE_URL}/products/{product_id}")
    detail_response.raise_for_status()
    details[product_id] = detail_response.json()

    price_response = session.get(f"{BASE_URL}/products/{product_id}/prices")
    price_response.raise_for_status()
    prices[product_id] = price_response.json()

# Request seasonal predictions for the next quarter. The API accepts a season,
# so use the upcoming season when it can be determined from the current month.
from datetime import date

month = date.today().month
if month in (12, 1, 2):
    next_season = "Spring"
elif month in (3, 4, 5):
    next_season = "Summer"
elif month in (6, 7, 8):
    next_season = "Fall"
else:
    next_season = "Winter"

predictions_response = session.post(
    f"{BASE_URL}/seasonal-trends/predictions",
    json={"itemIds": product_ids, "season": next_season},
)
predictions_response.raise_for_status()
seasonal_predictions = predictions_response.json()

# The documented API provides price retrieval but no endpoint for submitting
# price updates or suggested changes. Compare returned retailer prices locally
# to identify discrepancies.
price_discrepancies = {}
for product_id, price_data in prices.items():
    if isinstance(price_data, dict):
        entries = price_data.get("prices", price_data.get("retailers", []))
    elif isinstance(price_data, list):
        entries = price_data
    else:
        entries = []

    retailer_prices = []
    for entry in entries:
        if not isinstance(entry, dict):
            continue
        value = entry.get("price")
        if isinstance(value, (int, float)):
            retailer_prices.append(
                {
                    "retailer": entry.get("retailer") or entry.get("retailerName") or entry.get("retailerId"),
                    "price": value,
                }
            )

    if len(retailer_prices) > 1:
        values = [entry["price"] for entry in retailer_prices]
        if min(values) != max(values):
            price_discrepancies[product_id] = {
                "retailerPrices": retailer_prices,
                "suggestedReferencePrice": sum(values) / len(values),
            }

result = {
    "topRatedProducts": products,
    "productDetails": details,
    "seasonalPredictions": seasonal_predictions,
    "priceInformation": prices,
    "priceDiscrepanciesAndSuggestedReferencePrices": price_discrepancies,
}

