import requests

BASE_URL = "https://api.socbench.example"
session = requests.Session()

def get_json(path, **kwargs):
    response = session.get(f"{BASE_URL}{path}", **kwargs)
    response.raise_for_status()
    return response.json()

top_categories = get_json("/product-categories/top")
inventory_levels = get_json("/inventory-levels")
retailers = get_json("/retailers")
locations = get_json("/locations")

def records(data):
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        for key in ("categories", "data", "results", "retailers", "locations", "inventory"):
            value = data.get(key)
            if isinstance(value, list):
                return value
    return []

category_records = records(top_categories)
retailer_records = records(retailers)
location_records = records(locations)
inventory_records = records(inventory_levels)

category_ids = {
    str(category.get("id", category.get("categoryId", category.get("category_id", ""))))
    for category in category_records
    if isinstance(category, dict)
}
category_names = {
    str(category.get("name", category.get("category", ""))).strip().casefold()
    for category in category_records
    if isinstance(category, dict)
}
category_ids.discard("")
category_names.discard("")

retailer_products = {}
for retailer in retailer_records:
    if not isinstance(retailer, dict):
        continue
    retailer_id = retailer.get("id", retailer.get("retailerId", retailer.get("retailer_id")))
    if retailer_id is None:
        continue
    response = session.get(f"{BASE_URL}/retailers/{retailer_id}/products")
    response.raise_for_status()
    retailer_products[str(retailer_id)] = records(response.json())

def product_matches_category(product):
    if not isinstance(product, dict):
        return False
    category = product.get("category")
    category_id = product.get("categoryId", product.get("category_id"))
    if isinstance(category, dict):
        category_id = category.get("id", category.get("categoryId", category_id))
        category = category.get("name", category.get("category"))
    return (
        (category_id is not None and str(category_id) in category_ids)
        or (category is not None and str(category).strip().casefold() in category_names)
    )

retailers_by_category = {}
for retailer in retailer_records:
    if not isinstance(retailer, dict):
        continue
    retailer_id = retailer.get("id", retailer.get("retailerId", retailer.get("retailer_id")))
    if retailer_id is None:
        continue
    matching_products = [
        product for product in retailer_products.get(str(retailer_id), [])
        if product_matches_category(product)
    ]
    if matching_products:
        retailers_by_category[str(retailer_id)] = {
            "retailer": retailer,
            "products": matching_products,
        }

def inventory_matches_category(item):
    if not isinstance(item, dict):
        return False
    category = item.get("category")
    category_id = item.get("categoryId", item.get("category_id"))
    if isinstance(category, dict):
        category_id = category.get("id", category.get("categoryId", category_id))
        category = category.get("name", category.get("category"))
    return (
        (category_id is not None and str(category_id) in category_ids)
        or (category is not None and str(category).strip().casefold() in category_names)
    )

relevant_inventory = [
    item for item in inventory_records
    if inventory_matches_category(item)
]

feedback = {
    "gaps": [],
    "discrepancies": [],
}
represented_ids = set()
represented_names = set()
for item in relevant_inventory:
    if isinstance(item, dict):
        category_id = item.get("categoryId", item.get("category_id"))
        category = item.get("category")
        if isinstance(category, dict):
            category_id = category.get("id", category.get("categoryId", category_id))
            category = category.get("name", category.get("category"))
        if category_id is not None:
            represented_ids.add(str(category_id))
        if category:
            represented_names.add(str(category).strip().casefold())

for category in category_records:
    if not isinstance(category, dict):
        continue
    category_id = category.get("id", category.get("categoryId", category.get("category_id")))
    category_name = str(category.get("name", category.get("category", ""))).strip()
    if (
        (category_id is not None and str(category_id) not in represented_ids)
        and (not category_name or category_name.casefold() not in represented_names)
    ):
        feedback["gaps"].append({
            "category": category_name or None,
            "category_id": category_id,
            "issue": "Top-demand category has no matching inventory records.",
        })

for retailer_id, details in retailers_by_category.items():
    if not details["products"]:
        feedback["discrepancies"].append({
            "retailer_id": retailer_id,
            "issue": "Retailer identified without matching products in top-demand categories.",
        })

analysis = {
    "top_categories": top_categories,
    "inventory_levels": relevant_inventory,
    "retailers_offering_top_categories": [
        {
            "retailer": details["retailer"],
            "products": details["products"],
        }
        for details in retailers_by_category.values()
    ],
    "available_retailers": retailers,
    "store_locations": locations,
    "feedback": feedback,
}

response = session.post(f"{BASE_URL}/search", json={
    "query": (
        "Feedback on product availability and category representation: "
        f"{feedback}"
    )
})
response.raise_for_status()

print(analysis)
print({"feedback_submission": response.json()})

